-- Owner-run, rollback-only integration tests. No real games or Auth users touched.
-- Uses actual client roles and synthetic UUID identities.
do $test$
declare
 h text:='7c499999-0000-4000-8000-000000000001'; a text:='7c499999-0000-4000-8000-000000000002';
 b text:='7c499999-0000-4000-8000-000000000003'; c text:='7c499999-0000-4000-8000-000000000004';
 outsider text:='7c499999-0000-4000-8000-000000000005';
 code text; teamcode text; rematch text; q record; g jsonb; r jsonb; n jsonb; owner_g jsonb; rejected boolean;
 leader text; mate text; blueleader text; idx int; checks int:=0; result jsonb;
begin
 begin
  code:=quiz_private.new_code(); teamcode:=quiz_private.new_code();
  select c.*,a.correct_index into q from quiz_private.question_catalog c join public.question_answers a using(id) where a.correct_index is not null and c.difficulty=3 limit 1;
  perform set_config('request.jwt.claims',jsonb_build_object('sub',h,'role','authenticated')::text,true);
  set local role authenticated;
  r:=public.create_game(code,'Audit Host'); g:=r->'game';
  if g->>'status'<>'lobby' or (g#>>array['players',h,'score'])::int<>0 then raise exception 'creation defaults'; end if; checks:=checks+1;
  r:=public.apply_game_update(code,g || jsonb_build_object('winScore',10,'version',1)); g:=r->'game';
  if not (r->>'ok')::boolean then raise exception 'host target'; end if;
  perform set_config('request.jwt.claims',jsonb_build_object('sub',a,'role','authenticated')::text,true);
  r:=public.join_game(code,'Audit Member'); g:=r->'game';
  rejected:=false; begin perform public.leave_game(code,h); exception when insufficient_privilege then rejected:=true; end;
  if not rejected then raise exception 'member removed host'; end if; checks:=checks+1;
  rejected:=false; begin insert into public.games values('BAD999',g || jsonb_build_object('status','finished')); exception when insufficient_privilege then rejected:=true; end;
  if not rejected then raise exception 'direct insert accepted'; end if; checks:=checks+1;
  rejected:=false; begin perform data from quiz_private.games limit 1; exception when insufficient_privilege then rejected:=true; end;
  if not rejected then raise exception 'private state readable'; end if; checks:=checks+1;
  rejected:=false; begin perform id from public.question_answers limit 1; exception when insufficient_privilege then rejected:=true; end;
  if not rejected then raise exception 'answer key readable'; end if; checks:=checks+1;
  perform set_config('request.jwt.claims',jsonb_build_object('sub',outsider,'role','authenticated')::text,true);
  if public.get_game(code) is not null then raise exception 'outsider read'; end if;
  r:=public.apply_game_update(code,g || jsonb_build_object('version',(g->>'version')::int+1));
  if r->>'reason'<>'not_member' then raise exception 'outsider write'; end if; checks:=checks+1;
  set local role anon;
  rejected:=false; begin perform id from public.games where id=code; exception when insufficient_privilege then rejected:=true; end;
  if not rejected or has_function_privilege('anon','public.get_game(text)','execute') then raise exception 'anon exposure'; end if; checks:=checks+1;
  set local role authenticated;
  perform set_config('request.jwt.claims',jsonb_build_object('sub',h,'role','authenticated')::text,true);
  g:=public.get_game(code);
  r:=public.apply_game_update(code,g || jsonb_build_object('status','turn_reveal','turnOrder',jsonb_build_array(a,h),'currentTurnIndex',0,'version',(g->>'version')::int+1));g:=r->'game';
  r:=public.apply_game_update(code,g || jsonb_build_object('status','picking','currentTurn',jsonb_build_object('timerStartedAt',0,'resolved',jsonb_build_object(a,jsonb_build_object('earned',999))),'version',(g->>'version')::int+1));g:=r->'game';
  if g#>'{currentTurn,resolved}' is not null or (g#>>'{currentTurn,timerStartedAt}')::bigint<extract(epoch from clock_timestamp())*1000-10000 then raise exception 'client initial turn trusted'; end if; checks:=checks+1;
  perform set_config('request.jwt.claims',jsonb_build_object('sub',g#>>'{currentTurn,activePlayerId}','role','authenticated')::text,true);
  n:=g || jsonb_build_object('status','question','version',(g->>'version')::int+1,'usedQuestionIds',jsonb_build_array(q.id),'currentTurn',(g->'currentTurn') || jsonb_build_object('questionId',q.id,'selectedCategory',q.category,'selectedPoints',3,'timerStartedAt',0,'status','question'));
  r:=public.apply_game_update(code,n);g:=r->'game';
  if not (r->>'ok')::boolean or (g#>>'{currentTurn,timerStartedAt}')::bigint<extract(epoch from clock_timestamp())*1000-10000 then raise exception 'pick failed/deadline trusted'; end if; checks:=checks+1;
  perform set_config('request.jwt.claims',jsonb_build_object('sub',a,'role','authenticated')::text,true);
  g:=public.get_game(code);
  r:=public.apply_game_update(code,jsonb_set(g,array['players',a,'isHost'],'true') || jsonb_build_object('version',(g->>'version')::int+1));
  if r->>'reason'<>'rejected' then raise exception 'host escalation'; end if; checks:=checks+1;
  n:=jsonb_set(g,array['currentTurn','activeHelps',a],jsonb_build_object('double',true)) || jsonb_build_object('version',(g->>'version')::int+1);
  r:=public.apply_game_update(code,n);if r->>'reason'<>'rejected' then raise exception 'unspent double'; end if; checks:=checks+1;
  r:=public.use_power_up(code,'double');g:=r->'game';
  if not (g#>>array['players',a,'usedHelps','double'])::boolean or not (g#>>array['currentTurn','activeHelps',a,'double'])::boolean then raise exception 'double not atomic'; end if;
  rejected:=false;begin perform public.use_power_up(code,'double');exception when others then rejected:=true;end;
  if not rejected then raise exception 'double reusable'; end if; checks:=checks+1;
  n:=g || jsonb_build_object('version',(g->>'version')::int+1,'status','reviewing','players',(g->'players')-h,'currentTurn',(g->'currentTurn') || jsonb_build_object('status','reviewing','resolved',jsonb_build_object(a,jsonb_build_object('earned',999))));
  r:=public.apply_game_update(code,n);if r->>'reason'<>'rejected' then raise exception 'forged leave resolution'; end if; checks:=checks+1;
  perform set_config('request.jwt.claims',jsonb_build_object('sub',h,'role','authenticated')::text,true);
  r:=public.submit_answer(code,q.correct_index);g:=r->'game';
  if g#>array['currentTurn','answers',h,'answerIndex'] is null or g#>array['currentTurn','answers',h,'isCorrect'] is not null then raise exception 'own view wrong'; end if; checks:=checks+1;
  rejected:=false;begin perform public.use_power_up(code,'double');exception when others then rejected:=true;end;
  if not rejected then raise exception 'post-answer help'; end if;checks:=checks+1;
  perform set_config('request.jwt.claims',jsonb_build_object('sub',a,'role','authenticated')::text,true);
  g:=public.get_game(code);
  if g#>array['currentTurn','answers',h,'answerIndex'] is not null or g#>array['currentTurn','answers',h,'isCorrect'] is not null then raise exception 'opponent answer leaked'; end if;
  select data into n from public.games where id=code;
  if n#>array['currentTurn','answers',h,'answerIndex'] is not null then raise exception 'realtime answer leaked'; end if; checks:=checks+1;
  set local role postgres;
  update quiz_private.games set data=jsonb_set(data,'{currentTurn,timerStartedAt}','0') where id=code;
  set local role authenticated;
  r:=public.submit_answer(code,q.correct_index);g:=r->'game';
  if g->>'status'<>'reviewing' or (g#>>array['currentTurn','resolved',a,'earned'])::int<>0 then raise exception 'late answer scored'; end if;checks:=checks+1;
  rejected:=false;begin perform public.close_review(code);exception when insufficient_privilege then rejected:=true;end;
  if not rejected then raise exception 'nonhost early close'; end if;checks:=checks+1;
  perform set_config('request.jwt.claims',jsonb_build_object('sub',h,'role','authenticated')::text,true);
  r:=public.close_review(code);g:=r->'game';
  if (g#>>array['players',h,'score'])::int<>3 or g->>'status'<>'picking' then raise exception 'normal scoring/advance'; end if;checks:=checks+1;
  -- Independent scheduler timeout and a complete endgame fixture.
  set local role postgres;
  update quiz_private.games set data=jsonb_set(data,array['players',h,'score'],'9') where id=code;
  set local role authenticated;
  g:=public.get_game(code);
  perform set_config('request.jwt.claims',jsonb_build_object('sub',g#>>'{currentTurn,activePlayerId}','role','authenticated')::text,true);
  -- Use a different question for the next round.
  set local role postgres;
  select cc.*,aa.correct_index into q from quiz_private.question_catalog cc join public.question_answers aa using(id) where aa.correct_index is not null and cc.difficulty=3 and cc.id<>q.id limit 1;
  set local role authenticated;
  n:=g || jsonb_build_object('status','question','version',(g->>'version')::int+1,'currentTurn',(g->'currentTurn') || jsonb_build_object('questionId',q.id,'selectedCategory',q.category,'selectedPoints',3,'timerStartedAt',0,'status','question'));
  r:=public.apply_game_update(code,n);g:=r->'game';
  perform set_config('request.jwt.claims',jsonb_build_object('sub',h,'role','authenticated')::text,true);
  perform public.submit_answer(code,q.correct_index);
  set local role postgres;
  update quiz_private.games set data=jsonb_set(data,'{currentTurn,timerStartedAt}','0') where id=code;
  perform quiz_private.sweep_expired_questions();
  set local role authenticated;
  g:=public.get_game(code);if g->>'status'<>'reviewing' then raise exception 'scheduler failed';end if;checks:=checks+1;
  r:=public.close_review(code);g:=r->'game';
  if g->>'winnerId'<>h or (g#>>array['players',h,'score'])::int<>12 then raise exception 'winner not authoritative';end if;checks:=checks+1;
  r:=public.create_rematch(code);rematch:=r#>>'{game,rematchGameId}';g:=public.get_game(rematch);
  if g->>'status'<>'lobby' or (g#>>array['players',h,'score'])::int<>0 or (g#>>array['seriesWins',h])::int<>1 then raise exception 'rematch derivation';end if;
  r:=public.create_rematch(code);if r#>>'{game,rematchGameId}'<>rematch then raise exception 'duplicate rematch';end if;checks:=checks+1;
  -- Team privacy and leader-only scoring.
  r:=public.create_game(teamcode,'Audit Host');
  perform set_config('request.jwt.claims',jsonb_build_object('sub',a,'role','authenticated')::text,true);perform public.join_game(teamcode,'Audit A');
  perform set_config('request.jwt.claims',jsonb_build_object('sub',b,'role','authenticated')::text,true);perform public.join_game(teamcode,'Audit B');
  perform set_config('request.jwt.claims',jsonb_build_object('sub',c,'role','authenticated')::text,true);perform public.join_game(teamcode,'Audit C');
  perform set_config('request.jwt.claims',jsonb_build_object('sub',h,'role','authenticated')::text,true);
  perform public.set_game_mode(teamcode,'teams');r:=public.start_team_game(teamcode);g:=r->'game';
  r:=public.apply_game_update(teamcode,g || jsonb_build_object('status','picking','currentTurn','{}'::jsonb,'version',(g->>'version')::int+1));g:=r->'game';
  perform set_config('request.jwt.claims',jsonb_build_object('sub',g#>>'{currentTurn,activePlayerId}','role','authenticated')::text,true);
  r:=public.apply_game_update(teamcode,g || jsonb_build_object('status','question','version',(g->>'version')::int+1,'currentTurn',(g->'currentTurn') || jsonb_build_object('questionId',q.id,'selectedCategory',q.category,'selectedPoints',3,'timerStartedAt',0,'status','question')));g:=r->'game';
  leader:=g#>>'{teams,red,leaderId}';blueleader:=g#>>'{teams,blue,leaderId}';
  select value into mate from jsonb_array_elements_text(g#>'{teams,red,memberIds}') where value<>leader limit 1;
  perform set_config('request.jwt.claims',jsonb_build_object('sub',mate,'role','authenticated')::text,true);perform public.submit_answer(teamcode,q.correct_index);
  perform set_config('request.jwt.claims',jsonb_build_object('sub',leader,'role','authenticated')::text,true);g:=public.get_game(teamcode);
  if g#>array['currentTurn','answers',mate,'answerIndex'] is null or g#>array['currentTurn','answers',mate,'isCorrect'] is not null then raise exception 'team advice';end if;checks:=checks+1;
  perform public.submit_answer(teamcode,q.correct_index);
  perform set_config('request.jwt.claims',jsonb_build_object('sub',blueleader,'role','authenticated')::text,true);g:=public.get_game(teamcode);
  if g#>array['currentTurn','answers',mate,'answerIndex'] is not null then raise exception 'opponent team leak';end if;checks:=checks+1;
  r:=public.submit_answer(teamcode,(q.correct_index+1)%4);g:=r->'game';
  if g->>'status'<>'reviewing' or (g#>>'{currentTurn,teamResolved,red,earned}')::int<>3 then raise exception 'team resolution';end if;
  perform set_config('request.jwt.claims',jsonb_build_object('sub',h,'role','authenticated')::text,true);r:=public.close_review(teamcode);g:=r->'game';
  if (g#>>'{teams,red,score}')::int<>3 or (g#>>array['players',leader,'score'])::int<>0 then raise exception 'team banking';end if;checks:=checks+1;
  -- Numeric questions, Double scoring, and cross-team privacy.
  set local role postgres;
  select cc.*,aa.correct_value into q from quiz_private.question_catalog cc join public.question_answers aa using(id) where aa.correct_value is not null and cc.difficulty=1 limit 1;
  set local role authenticated;
  perform set_config('request.jwt.claims',jsonb_build_object('sub',g#>>'{currentTurn,activePlayerId}','role','authenticated')::text,true);
  r:=public.apply_game_update(teamcode,g || jsonb_build_object('status','question','version',(g->>'version')::int+1,'currentTurn',(g->'currentTurn') || jsonb_build_object('questionId',q.id,'selectedCategory',q.category,'selectedPoints',1,'timerStartedAt',0,'status','question')));g:=r->'game';
  perform set_config('request.jwt.claims',jsonb_build_object('sub',leader,'role','authenticated')::text,true);
  r:=public.use_fifty(teamcode);if r->>'reason' is distinct from 'not_a_choice_question' then raise exception 'numeric fifty permitted';end if;checks:=checks+1;
  perform public.use_power_up(teamcode,'double');perform public.submit_answer(teamcode,null,q.correct_value);
  perform set_config('request.jwt.claims',jsonb_build_object('sub',blueleader,'role','authenticated')::text,true);g:=public.get_game(teamcode);
  if g#>array['currentTurn','answers',leader,'answerValue'] is not null then raise exception 'numeric guess leaked';end if;checks:=checks+1;
  r:=public.submit_answer(teamcode,null,q.correct_value+10);g:=r->'game';
  if (g#>>'{currentTurn,teamResolved,red,earned}')::int is distinct from 2 then raise exception 'numeric Double scoring';end if;checks:=checks+1;
  perform set_config('request.jwt.claims',jsonb_build_object('sub',h,'role','authenticated')::text,true);r:=public.close_review(teamcode);g:=r->'game';
  -- Leader departure during a choice question promotes the remaining teammate.
  set local role postgres;
  select cc.*,aa.correct_index into q from quiz_private.question_catalog cc join public.question_answers aa using(id) where aa.correct_index is not null and cc.difficulty=3 and not (g->'usedQuestionIds' ? cc.id) limit 1;
  set local role authenticated;
  perform set_config('request.jwt.claims',jsonb_build_object('sub',g#>>'{currentTurn,activePlayerId}','role','authenticated')::text,true);
  n:=g || jsonb_build_object('status','question','version',(g->>'version')::int+1,'currentTurn',(g->'currentTurn') || jsonb_build_object('questionId',q.id,'selectedCategory',q.category,'selectedPoints',1,'timerStartedAt',0,'status','question'));
  rejected:=false;begin perform public.apply_game_update(teamcode,n);exception when others then rejected:=true;end;
  if not rejected then raise exception 'question stake tampering';end if;checks:=checks+1;
  n:=jsonb_set(n,'{currentTurn,selectedPoints}','3');r:=public.apply_game_update(teamcode,n);g:=r->'game';
  perform set_config('request.jwt.claims',jsonb_build_object('sub',leader,'role','authenticated')::text,true);perform public.leave_game(teamcode,leader);
  perform set_config('request.jwt.claims',jsonb_build_object('sub',mate,'role','authenticated')::text,true);g:=public.get_game(teamcode);
  if g->>'status' is distinct from 'question' or g->'players' ? leader then raise exception 'leader departure';end if;checks:=checks+1;
  r:=public.use_fifty(teamcode);
  if jsonb_array_length(r->'hidden') is distinct from 2 or r->'hidden' @> to_jsonb(array[q.correct_index]) then raise exception 'fifty hid correct answer';end if;checks:=checks+1;
  perform public.submit_answer(teamcode,q.correct_index);
  perform set_config('request.jwt.claims',jsonb_build_object('sub',blueleader,'role','authenticated')::text,true);
  r:=public.submit_answer(teamcode,null,null,mate);g:=r->'game';
  if g->>'status' is distinct from 'reviewing' or (g#>>'{currentTurn,teamResolved,red,earned}')::int is distinct from 1 or (g#>>'{currentTurn,teamResolved,blue,earned}')::int is distinct from 3 then raise exception 'steal/50 cap/leader fallback';end if;checks:=checks+1;
  -- A leader leaving after results cannot require an unanswered successor to submit.
  -- Owner edits only this synthetic fixture to restore an unanswered teammate.
  set local role postgres;
  g:=jsonb_set(g,array['players',leader],jsonb_build_object('id',leader,'name','Audit returning teammate','isHost',false,'joinedAt',0,'score',0,'usedHelps',jsonb_build_object('fifty',false,'double',false,'steal',false,'sabotage',false)));
  g:=jsonb_set(g,'{currentTurn,answers}',(g#>'{currentTurn,answers}')-leader);
  update quiz_private.games set data=g where id=teamcode;
  set local role authenticated;
  perform set_config('request.jwt.claims',jsonb_build_object('sub',mate,'role','authenticated')::text,true);
  perform public.leave_game(teamcode,mate);
  set local role postgres;
  select key into leader from quiz_private.games, lateral jsonb_each(data->'players') where id=teamcode and (value->>'isHost')::boolean;
  set local role authenticated;
  perform set_config('request.jwt.claims',jsonb_build_object('sub',leader,'role','authenticated')::text,true);
  r:=public.close_review(teamcode);
  if r#>>'{game,status}'='reviewing' or not (r->>'ok')::boolean then raise exception 'leader review departure stalled game';end if;checks:=checks+1;
  -- Restore host identity for the independent solo rematch fixture below.
  perform set_config('request.jwt.claims',jsonb_build_object('sub',h,'role','authenticated')::text,true);

  -- A real leave transfers host with no arbitrary state parameter.
  r:=public.leave_game(rematch,h);
  perform set_config('request.jwt.claims',jsonb_build_object('sub',a,'role','authenticated')::text,true);g:=public.get_game(rematch);
  if g->'players' ? h or not (g#>>array['players',a,'isHost'])::boolean then raise exception 'host transfer';end if;checks:=checks+1;
  raise exception using errcode='ZA002',message='rollback test games';
 exception when sqlstate 'ZA002' then null;
 end;
 result:=jsonb_build_object('passed',checks,'synthetic_games_remaining',(select count(*) from public.games where id in(code,teamcode,rematch)));
 perform set_config('quiz_security_regression.results',result::text,false);
end $test$;
select current_setting('quiz_security_regression.results')::jsonb as regression_results;
